   311→        let insertIndex = state.frames.length;
   312→        if (insertAfter) {
   313→          const afterIndex = state.frames.findIndex((f) => f.id === insertAfter);
   314→          if (afterIndex !== -1) {
   315→            insertIndex = afterIndex + 1;
   316→          }
   317→        }
   318→
   319→        const newFrames = [...state.frames];
   320→        newFrames.splice(insertIndex, 0, ...duplicates);
   321→        return { frames: newFrames, totalFrameCount: newFrames.length, isDirty: true };
   322→      }),
   323→
   324→    // Frame delay management
   325→    setFrameDelay: (frameId, delay) =>
   326→      set((state) => ({
   327→        frames: state.frames.map((f) =>
   328→          f.id === frameId ? { ...f, metadata: { ...f.metadata, delay } } : f
