    ctx.lineJoin = 'round';
    ctx.globalAlpha = overlay.opacity;

    ctx.beginPath();
    ctx.moveTo(overlay.points[0].x, overlay.points[0].y);

    for (let i = 1; i < overlay.points.length; i++) {
      ctx.lineTo(overlay.points[i].x, overlay.points[i].y);
