import { useCallback, useRef, useEffect, useState, forwardRef, useImperativeHandle } from 'react';

export interface TextOverlay {
  id: string;
  type: 'text';
  text: string;
  x: number;
  y: number;
  fontSize: number;
  fontFamily: string;
  color: string;
  backgroundColor?: string;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  rotation?: number;
}

export interface ShapeOverlay {
  id: string;
  type: 'rectangle' | 'ellipse' | 'line' | 'arrow';
  x: number;
  y: number;
  width: number;
  height: number;
  strokeColor: string;
  strokeWidth: number;
  fillColor?: string;
  rotation?: number;
}

export interface DrawingOverlay {
  id: string;
  type: 'drawing';
  points: { x: number; y: number }[];
  color: string;
  width: number;
  opacity: number;
