            onShowFrameDelaysChange={editorStore.setShowFrameDelays}
            onScrubStart={playback.pause}
          />
        </div>

        {/* Right properties panel */}
        <aside className="w-72 bg-surface-800 border-l border-surface-700 overflow-y-auto">
          {renderRightPanel()}
        </aside>
