      {/* Status bar */}
      <StatusBar
        status={isDirty ? 'warning' : 'idle'}
        statusMessage={isDirty ? 'Unsaved changes' : 'Ready'}
        leftItems={statusLeftItems}
        rightItems={statusRightItems}
      />
    </div>
  );
}

